    if (mode === 't') return '<rect fill="currentColor" fill-opacity=".2"' + at + '/>';
    if (mode === 'p') return '<rect fill="currentColor" stroke="none"' + at + '/>';
    if (mode === 'kp') return '<rect class="kp" fill="currentColor" stroke="none"' + at + '/>';
    return '<rect' + at + '/>';
